arguments.argument:
ini_open("gg2.ini");
global.timeLimitMins = ini_read_real("Server", "Time Limit", 15);
global.caplimit = ini_read_real("Server", "CapLimit", 5);
global.Server_RespawntimeSec = ini_read_real("Server", "Respawn Time", 5);
readClasslimitsFromIni();
ini_close();

//Server respawn time calculator. Converts each second to a frame. (read: multiply by 30 :hehe:)
if (global.Server_RespawntimeSec == 0)
    global.Server_Respawntime = 1;
else
    global.Server_Respawntime = global.Server_RespawntimeSec * 30;

menu_create(48, 172, 500, 260, 32, 40, 112, 128);
menumode = true;

menu_background(512, 24, 8, 12, 4);
bgtabs = true;

menu_addedit_text2("Server Name:", "global.serverName", menu_host_options_server_name);
menu_addedit_text2("Welcome message:", "global.welcomeMessage", menu_host_options_welcome_message);

menu_addedit_text("Password:", "global.serverPassword", menu_host_options_password);
menu_addedit_num("Player Limit:", "global.playerLimit", menu_host_options_player_limit, 48);
menu_addedit_num("Time Limit (mins):", "global.timeLimitMins", menu_host_options_time_limit_mins);
menu_addedit_num("Capture Limit:", "global.caplimit", menu_host_options_capture_limit);
menu_addedit_num("Deathmatch Kill Limit:", "global.killLimit", menu_host_options_deathmatch_kill_limit);
menu_addedit_num("TDM Invulnerability (secs):", "global.tdmInvulnerabilitySeconds", menu_host_options_tdm_invulnerability_secs);
menu_addedit_num("Respawn Time (secs):", "global.Server_RespawntimeSec", menu_host_options_respawn_time_secs);


menu_addtablink("Main", menu_host_tab_main);
menu_addtablink("Advanced", menu_host_tab_advanced);
menu_addtablink("Classlimits", menu_host_tab_classlimits);

menu_addlink("Start Game", menu_host_start_game);
menu_addback("Back", menu_host_back);
